CREATE TYPE public.escala_regime AS ENUM ('5x2','compensatorio_cct');
CREATE TYPE public.escala_status_dia AS ENUM ('TRABALHO','FOLGA','FOLGA_COMP','FERIAS','ATESTADO','AFASTADO','FERIADO');
CREATE TYPE public.escala_tipo_data AS ENUM ('feriado','pico');
CREATE TYPE public.escala_status_periodo AS ENUM ('rascunho','publicada');
CREATE TABLE public.escala_config_loja (store_id uuid PRIMARY KEY REFERENCES public.stores(id) ON DELETE CASCADE, regime public.escala_regime NOT NULL DEFAULT '5x2', semana_inicia smallint NOT NULL DEFAULT 1 CHECK (semana_inicia IN (0,1)), acordo_compensacao boolean NOT NULL DEFAULT true, intervalo_min_minutos smallint NOT NULL DEFAULT 60 CHECK (intervalo_min_minutos BETWEEN 15 AND 120), domingo_folga_cada_semanas smallint NOT NULL DEFAULT 3 CHECK (domingo_folga_cada_semanas BETWEEN 1 AND 7), feriado_autorizado_cct boolean NOT NULL DEFAULT false, preferir_folgas_seguidas boolean NOT NULL DEFAULT true, max_dias_consecutivos smallint NOT NULL DEFAULT 6 CHECK (max_dias_consecutivos BETWEEN 1 AND 6), cct_referencia text, cct_vigencia_fim date, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_config_loja TO authenticated; GRANT ALL ON public.escala_config_loja TO service_role;
ALTER TABLE public.escala_config_loja ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.escala_marcos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid REFERENCES public.stores(id) ON DELETE CASCADE, vigencia_inicio date NOT NULL, horas_semanais numeric(4,1) NOT NULL CHECK (horas_semanais BETWEEN 20 AND 44), folgas_semanais smallint NOT NULL CHECK (folgas_semanais BETWEEN 1 AND 3), rotulo text NOT NULL, base_legal text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_marcos TO authenticated; GRANT ALL ON public.escala_marcos TO service_role; ALTER TABLE public.escala_marcos ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX ux_escala_marcos ON public.escala_marcos(coalesce(store_id,'00000000-0000-0000-0000-000000000000'::uuid),vigencia_inicio);
CREATE TABLE public.escala_turnos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, departamento text, codigo text NOT NULL, nome text, inicio time NOT NULL, fim time NOT NULL, intervalo_min smallint NOT NULL DEFAULT 60 CHECK (intervalo_min BETWEEN 0 AND 240), cor text NOT NULL DEFAULT '#CA3155', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,codigo));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_turnos TO authenticated; GRANT ALL ON public.escala_turnos TO service_role; ALTER TABLE public.escala_turnos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.escala_funcionarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, nome text NOT NULL, matricula text, departamento text NOT NULL, cargo text, turno_padrao_id uuid REFERENCES public.escala_turnos(id) ON DELETE SET NULL, data_nascimento date, aprendiz boolean NOT NULL DEFAULT false, domingo_quinzenal boolean NOT NULL DEFAULT false, carga_semanal_contratual numeric(4,1), folga_preferida smallint CHECK(folga_preferida BETWEEN 0 AND 6), admissao date, desligamento date, celular text, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,matricula));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_funcionarios TO authenticated; GRANT ALL ON public.escala_funcionarios TO service_role; ALTER TABLE public.escala_funcionarios ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.escala_cobertura (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, departamento text NOT NULL, dia_semana smallint NOT NULL CHECK(dia_semana BETWEEN 0 AND 6), turno_id uuid REFERENCES public.escala_turnos(id) ON DELETE CASCADE, minimo smallint NOT NULL DEFAULT 0 CHECK(minimo>=0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_cobertura TO authenticated; GRANT ALL ON public.escala_cobertura TO service_role; ALTER TABLE public.escala_cobertura ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX ux_escala_cobertura ON public.escala_cobertura(store_id,departamento,dia_semana,coalesce(turno_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE public.escala_datas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid REFERENCES public.stores(id) ON DELETE CASCADE, data date NOT NULL, nome text NOT NULL, tipo public.escala_tipo_data NOT NULL DEFAULT 'feriado', loja_abre boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_datas TO authenticated; GRANT ALL ON public.escala_datas TO service_role; ALTER TABLE public.escala_datas ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX ux_escala_datas ON public.escala_datas(coalesce(store_id,'00000000-0000-0000-0000-000000000000'::uuid),data,tipo);
CREATE TABLE public.escala_ausencias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, funcionario_id uuid NOT NULL REFERENCES public.escala_funcionarios(id) ON DELETE CASCADE, tipo public.escala_status_dia NOT NULL CHECK(tipo IN ('FERIAS','ATESTADO','AFASTADO')), inicio date NOT NULL, fim date NOT NULL CHECK(fim>=inicio), observacao text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_ausencias TO authenticated; GRANT ALL ON public.escala_ausencias TO service_role; ALTER TABLE public.escala_ausencias ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.escala_periodos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, ano smallint NOT NULL, mes smallint NOT NULL CHECK(mes BETWEEN 1 AND 12), status public.escala_status_periodo NOT NULL DEFAULT 'rascunho', versao int NOT NULL DEFAULT 1, erros int NOT NULL DEFAULT 0 CHECK(erros>=0), alertas int NOT NULL DEFAULT 0 CHECK(alertas>=0), gerado_em timestamptz, gerado_por uuid, publicado_em timestamptz, publicado_por uuid, justificativa_publicacao text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,ano,mes));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_periodos TO authenticated; GRANT ALL ON public.escala_periodos TO service_role; ALTER TABLE public.escala_periodos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.escala_alocacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), periodo_id uuid NOT NULL REFERENCES public.escala_periodos(id) ON DELETE CASCADE, store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, funcionario_id uuid NOT NULL REFERENCES public.escala_funcionarios(id) ON DELETE CASCADE, data date NOT NULL, status public.escala_status_dia NOT NULL, turno_id uuid REFERENCES public.escala_turnos(id) ON DELETE SET NULL, inicio time, fim time, intervalo_min smallint, travado boolean NOT NULL DEFAULT false, origem text NOT NULL DEFAULT 'auto' CHECK(origem IN ('auto','manual')), observacao text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, UNIQUE(funcionario_id,data));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.escala_alocacoes TO authenticated; GRANT ALL ON public.escala_alocacoes TO service_role; ALTER TABLE public.escala_alocacoes ENABLE ROW LEVEL SECURITY;
CREATE INDEX ix_escala_aloc_periodo ON public.escala_alocacoes(periodo_id); CREATE INDEX ix_escala_aloc_store_data ON public.escala_alocacoes(store_id,data);
CREATE OR REPLACE FUNCTION public.escala_tem_acesso_loja(p_store uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.user_store_access WHERE user_id=auth.uid() AND store_id=p_store AND approved) $$;
CREATE OR REPLACE FUNCTION public.escala_pode_gerir(p_store uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR (public.escala_tem_acesso_loja(p_store) AND (public.is_supervisor(auth.uid()) OR EXISTS(SELECT 1 FROM public.user_module_access WHERE user_id=auth.uid() AND module='admin_escala' AND allowed))) $$;
REVOKE ALL ON FUNCTION public.escala_tem_acesso_loja(uuid),public.escala_pode_gerir(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.escala_tem_acesso_loja(uuid),public.escala_pode_gerir(uuid) TO authenticated,service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['escala_config_loja','escala_turnos','escala_funcionarios','escala_cobertura'] LOOP EXECUTE format('CREATE POLICY %1$s_sel ON public.%1$s FOR SELECT TO authenticated USING(public.escala_tem_acesso_loja(store_id))',t); EXECUTE format('CREATE POLICY %1$s_write ON public.%1$s FOR ALL TO authenticated USING(public.escala_pode_gerir(store_id)) WITH CHECK(public.escala_pode_gerir(store_id))',t); END LOOP; END $$;
CREATE POLICY escala_ausencias_gestao ON public.escala_ausencias FOR ALL TO authenticated USING(public.escala_pode_gerir(store_id)) WITH CHECK(public.escala_pode_gerir(store_id));
CREATE POLICY escala_periodos_sel ON public.escala_periodos FOR SELECT TO authenticated USING(public.escala_pode_gerir(store_id) OR (status='publicada' AND public.escala_tem_acesso_loja(store_id)));
CREATE POLICY escala_periodos_write ON public.escala_periodos FOR ALL TO authenticated USING(public.escala_pode_gerir(store_id)) WITH CHECK(public.escala_pode_gerir(store_id));
CREATE POLICY escala_alocacoes_sel ON public.escala_alocacoes FOR SELECT TO authenticated USING(public.escala_pode_gerir(store_id) OR (public.escala_tem_acesso_loja(store_id) AND EXISTS(SELECT 1 FROM public.escala_periodos p WHERE p.id=periodo_id AND p.status='publicada')));
CREATE POLICY escala_alocacoes_write ON public.escala_alocacoes FOR ALL TO authenticated USING(public.escala_pode_gerir(store_id)) WITH CHECK(public.escala_pode_gerir(store_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['escala_marcos','escala_datas'] LOOP EXECUTE format('CREATE POLICY %1$s_sel ON public.%1$s FOR SELECT TO authenticated USING(store_id IS NULL OR public.escala_tem_acesso_loja(store_id))',t); EXECUTE format('CREATE POLICY %1$s_write ON public.%1$s FOR ALL TO authenticated USING(CASE WHEN store_id IS NULL THEN public.has_role(auth.uid(),''admin'') ELSE public.escala_pode_gerir(store_id) END) WITH CHECK(CASE WHEN store_id IS NULL THEN public.has_role(auth.uid(),''admin'') ELSE public.escala_pode_gerir(store_id) END)',t); END LOOP; END $$;
CREATE FUNCTION public.escala_validar_vinculos() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid; BEGIN
IF TG_TABLE_NAME='escala_funcionarios' THEN tid:=NEW.turno_padrao_id; ELSIF TG_TABLE_NAME IN ('escala_alocacoes','escala_cobertura') THEN tid:=NEW.turno_id; END IF;
IF tid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.escala_turnos WHERE id=tid AND store_id=NEW.store_id) THEN RAISE EXCEPTION 'Turno não pertence à loja informada.' USING errcode='P0001'; END IF;
IF TG_TABLE_NAME IN ('escala_alocacoes','escala_ausencias') AND NOT EXISTS(SELECT 1 FROM public.escala_funcionarios WHERE id=NEW.funcionario_id AND store_id=NEW.store_id) THEN RAISE EXCEPTION 'Funcionário não pertence à loja informada.' USING errcode='P0001'; END IF;
IF TG_TABLE_NAME='escala_alocacoes' AND NOT EXISTS(SELECT 1 FROM public.escala_periodos WHERE id=NEW.periodo_id AND store_id=NEW.store_id AND ano=extract(year FROM NEW.data) AND mes=extract(month FROM NEW.data)) THEN RAISE EXCEPTION 'Data ou loja não pertence ao período informado.' USING errcode='P0001'; END IF; RETURN NEW; END $$;
CREATE TRIGGER escala_func_vinculo BEFORE INSERT OR UPDATE ON public.escala_funcionarios FOR EACH ROW EXECUTE FUNCTION public.escala_validar_vinculos();
CREATE TRIGGER escala_aus_vinculo BEFORE INSERT OR UPDATE ON public.escala_ausencias FOR EACH ROW EXECUTE FUNCTION public.escala_validar_vinculos();
CREATE TRIGGER escala_cob_vinculo BEFORE INSERT OR UPDATE ON public.escala_cobertura FOR EACH ROW EXECUTE FUNCTION public.escala_validar_vinculos();
CREATE TRIGGER escala_aloc_vinculo BEFORE INSERT OR UPDATE ON public.escala_alocacoes FOR EACH ROW EXECUTE FUNCTION public.escala_validar_vinculos();
CREATE FUNCTION public.escala_bloqueia_publicada() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE pid uuid; v_status public.escala_status_periodo; BEGIN
IF TG_OP<>'INSERT' THEN SELECT status INTO v_status FROM public.escala_periodos WHERE id=OLD.periodo_id FOR UPDATE; IF v_status='publicada' THEN RAISE EXCEPTION 'Escala publicada não pode ser alterada. Use Reabrir.' USING errcode='P0001'; END IF; END IF;
IF TG_OP<>'DELETE' THEN SELECT status INTO v_status FROM public.escala_periodos WHERE id=NEW.periodo_id FOR UPDATE; IF v_status='publicada' THEN RAISE EXCEPTION 'Escala publicada não pode ser alterada. Use Reabrir.' USING errcode='P0001'; END IF; NEW.updated_at:=now(); NEW.updated_by:=auth.uid(); RETURN NEW; END IF; RETURN OLD; END $$;
CREATE TRIGGER escala_aloc_bloqueio BEFORE INSERT OR UPDATE OR DELETE ON public.escala_alocacoes FOR EACH ROW EXECUTE FUNCTION public.escala_bloqueia_publicada();
CREATE FUNCTION public.escala_periodo_transicao() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
NEW.updated_at:=now(); IF TG_OP='INSERT' THEN IF NEW.status<>'rascunho' THEN RAISE EXCEPTION 'Crie a escala como rascunho antes de publicar.' USING errcode='P0001'; END IF; NEW.versao:=1; NEW.publicado_em:=NULL; NEW.publicado_por:=NULL; RETURN NEW; END IF;
IF NEW.store_id<>OLD.store_id OR NEW.ano<>OLD.ano OR NEW.mes<>OLD.mes THEN RAISE EXCEPTION 'O período e a loja não podem ser alterados.' USING errcode='P0001'; END IF;
IF OLD.status='publicada' THEN IF NEW.status='rascunho' THEN NEW.versao:=OLD.versao+1; NEW.publicado_em:=NULL; NEW.publicado_por:=NULL; ELSE RAISE EXCEPTION 'Reabra a escala antes de alterar o período.' USING errcode='P0001'; END IF;
ELSIF NEW.status='publicada' THEN IF NEW.erros>0 AND coalesce(trim(NEW.justificativa_publicacao),'')='' THEN RAISE EXCEPTION 'Escala com erros só pode ser publicada com justificativa.' USING errcode='P0001'; END IF; IF NOT EXISTS(SELECT 1 FROM public.escala_alocacoes WHERE periodo_id=NEW.id) THEN RAISE EXCEPTION 'Gere a escala antes de publicar.' USING errcode='P0001'; END IF; NEW.publicado_em:=now(); NEW.publicado_por:=auth.uid(); ELSE NEW.publicado_em:=NULL; NEW.publicado_por:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER escala_periodo_transicao BEFORE INSERT OR UPDATE ON public.escala_periodos FOR EACH ROW EXECUTE FUNCTION public.escala_periodo_transicao();
CREATE FUNCTION public.escala_validar_config() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.regime='compensatorio_cct' AND coalesce(trim(NEW.cct_referencia),'')='' THEN RAISE EXCEPTION 'Informe a referência da CCT para o regime compensatório.' USING errcode='P0001'; END IF; IF NEW.intervalo_min_minutos<60 AND coalesce(trim(NEW.cct_referencia),'')='' THEN RAISE EXCEPTION 'A redução do intervalo exige referência da CCT.' USING errcode='P0001'; END IF; NEW.updated_by:=auth.uid(); NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER escala_config_validar BEFORE INSERT OR UPDATE ON public.escala_config_loja FOR EACH ROW EXECUTE FUNCTION public.escala_validar_config();
COMMENT ON TABLE public.escala_marcos IS 'Marcos configuráveis de planejamento; propostas futuras não constituem certificação legal.';